let state={screen:'home',vibe:'surprise',member:0,votes:{Ronaldo:'like',Messi:'pass',Haaland:'like',Mbappe:'maybe'},completed:0,authed:localStorage.getItem('sidequest-auth')==='1',name:localStorage.getItem('sidequest-name')||'Maya',handle:localStorage.getItem('sidequest-handle')||'@maya',city:localStorage.getItem('sidequest-city')||'Dubai',friends:JSON.parse(localStorage.getItem('sidequest-friends')||'null')||['Ronaldo','Messi','Haaland','Mbappe']};
let compromiseData=null;
const app=document.querySelector('#app');
const esc=s=>s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
function layout(content){app.innerHTML=`<main class="shell"><nav class="topbar"><button class="brand brand-button" onclick="go('${state.authed?'home':'signin'}')" aria-label="Go to SideQuest home"><span class="brand-mark">✦</span> sidequest</button><div class="top-actions">${state.authed?`<button class="nav-link" onclick="go('home')">Home</button><button class="nav-link" onclick="go('friends')">Friends</button><button class="nav-link" onclick="go('profile')">${esc(state.name)}</button><button class="reset" onclick="signOut()">Sign out</button>`:''}</div></nav>${content}</main>`}
function signIn(){layout(`<section class="auth-screen"><div class="auth-card"><div class="brand"><span class="brand-mark">✦</span> sidequest</div><div class="eyebrow">YOUR FRIENDS. YOUR NEXT STORY.</div><h1>Stop saying<br><span class="accent">“we should.”</span></h1><p class="sub">SideQuest turns group chat energy into plans everyone actually wants to show up for.</p><input id="auth-name" class="request" placeholder="Your name" value="${state.name==='Maya'?'':state.name}"><input id="auth-email" class="request" placeholder="Email address" type="email"><button class="primary" onclick="createAccount()">Create my profile <span>→</span></button><small>Demo mode: no email is sent. Your profile stays on this device.</small></div><div class="auth-art"><div class="creature"></div><b>Find your people.<br>Find your thing.</b></div></section>`)}
function createAccount(){const name=document.querySelector('#auth-name').value.trim()||'Maya';state.name=name;state.handle='@'+name.toLowerCase().replace(/[^a-z0-9]+/g,'');state.authed=true;localStorage.setItem('sidequest-auth','1');localStorage.setItem('sidequest-name',name);localStorage.setItem('sidequest-handle',state.handle);go('home')}
function signOut(){state.authed=false;localStorage.removeItem('sidequest-auth');signIn()}
function profile(){layout(`<section class="screen"><div class="eyebrow">YOUR PROFILE</div><h2>Make your preferences easy to plan around.</h2><p class="sub">Friends see the useful stuff: your energy, your budget and what makes a great night for you.</p><div class="profile-layout"><div class="panel profile-hero"><div class="avatar a4 profile-avatar">${state.name[0].toUpperCase()}</div><h2>${esc(state.name)}</h2><p>${esc(state.handle)} · ${esc(state.city)}</p><span class="pill">WEEKEND WARRIOR</span></div><div class="panel"><div class="field"><label>HOME CITY</label><input id="city" class="request" value="${esc(state.city)}"></div><div class="field"><label>MY VIBES</label><div class="choice-row"><button class="choice active">Foodie</button><button class="choice active">Social</button><button class="choice">Chill</button><button class="choice">Adventure</button></div></div><div class="field"><label>MAX BUDGET PER PERSON</label><div class="choice-row"><button class="choice">AED 70</button><button class="choice active">AED 100</button><button class="choice">AED 150</button></div></div><button class="primary purple" onclick="saveProfile()">Save preferences</button></div></div></section>`)}
function saveProfile(){state.city=document.querySelector('#city').value.trim()||'Dubai';localStorage.setItem('sidequest-city',state.city);go('home')}
function friends(){const suggestions=[['Noor','@noor.jpg','Loves cafés · AED 80'],['Zain','@zainplays','Gaming · AED 100'],['Sara','@sara.eats','Foodie · AED 120']];layout(`<section class="screen"><div class="eyebrow">YOUR PEOPLE</div><h2>Plans start with the right people.</h2><p class="sub">Connect with friends, then invite them into a SideQuest when the group chat starts looping.</p><div class="friends-layout"><div class="panel"><div class="section-head"><h3>Your friends <span class="pill">${state.friends.length}</span></h3><button class="primary purple" onclick="go('invite')">+ Invite</button></div><div class="friend-list">${state.friends.map((f,i)=>`<div class="friend"><div class="avatar a${(i%4)+1}">${f[0]}</div><div><b>${esc(f)}</b><small>${i===0?'@Ronaldo · Activity lover':i===1?'@Messi · Keeps it casual':i===2?'@Haaland · Foodie':'@Mbappe · Competitive'}</small></div><span class="online">●</span></div>`).join('')}</div></div><div class="panel"><div class="eyebrow">PEOPLE YOU MAY KNOW</div>${suggestions.map((s,i)=>`<div class="friend suggestion"><div class="avatar a${i+1}">${s[0][0]}</div><div><b>${s[0]}</b><small>${s[2]}</small></div><button class="choice" onclick="addFriend('${s[0]}')">Add</button></div>`).join('')}</div></div></section>`)}
function addFriend(name){if(!state.friends.includes(name))state.friends.push(name);localStorage.setItem('sidequest-friends',JSON.stringify(state.friends));friends()}
function invite(){layout(`<section class="screen"><button class="back" onclick="go('friends')">← Friends</button><div class="eyebrow">GROW THE PARTY</div><h2>Bring your people into the plan.</h2><div class="panel invite-card"><p class="sub">Share this invite code in your group chat. Anyone can join the party and add their preferences.</p><div class="invite-code">SIDE-QUEST-42</div><button class="primary" onclick="navigator.clipboard?.writeText('SIDE-QUEST-42');this.textContent='Copied!'">Copy invite code</button></div></section>`)}
function home(){layout(`<section class="screen"><div class="hero"><div class="hero-copy"><div class="eyebrow">Your city. Your party. Your next story.</div><h1>Make plans worth remembering.</h1><p class="sub">SideQuest turns “what should we do?” into a shared adventure — tuned to everyone's tastes, budget and energy.</p><br><button class="primary" onclick="go('plan')">✨ Plan a SideQuest <span>→</span></button></div><div class="hero-art"><div class="orb"></div></div></div><div class="section-head"><div><div class="eyebrow">THE PARTY</div><h2>Weekend Warriors</h2></div><span class="pill">GROUP LEVEL 3</span></div><div class="members">${members.map(m=>`<article class="member"><div class="avatar ${m.avatar}">${m.initials}</div><h3>${m.name}</h3><small>WEEKEND WARRIOR</small><div class="tags">${m.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="budget">◈ AED ${m.budget} max</div></article>`).join('')}</div><div class="stats"><div class="stat"><strong>🔥 3</strong><span>Adventure streak</span></div><div class="stat"><strong>👾 3</strong><span>Vibies discovered</span></div><div class="stat"><strong>+680</strong><span>Group XP</span></div></div></section>`)}
function plan(){layout(`<section class="screen"><button class="back" onclick="go('home')">← Back to group</button><div class="eyebrow">QUEST BUILDER · 01</div><h2>What are we getting into?</h2><p class="sub">SideQuest Agent will cross-check everyone's preferences and find a plan the whole party can get behind.</p><div class="form-layout"><div class="panel"><div class="field"><label>WHEN?</label><div class="choice-row"><button class="choice active">Tonight</button><button class="choice">Tomorrow</button><button class="choice">This weekend</button></div></div><div class="field"><label>BUDGET PER PERSON</label><div class="choice-row"><button class="choice">AED 70</button><button class="choice active">AED 100</button><button class="choice">AED 150</button></div></div><div class="field"><label>WHAT'S THE VIBE?</label><div class="choice-row">${[['food','🍽 Food'],['activity','🎯 Activity'],['chill','😌 Chill'],['surprise','🎲 Surprise Me']].map(([id,t])=>`<button class="choice ${state.vibe===id?'active':''}" onclick="setVibe('${id}')">${t}</button>`).join('')}</div></div><div class="field"><label>OPTIONAL REQUEST</label><textarea class="request" rows="3">Something fun where we can eat and do an activity.</textarea></div><button class="primary purple" onclick="findPlans()">✨ Find our SideQuest <span>→</span></button></div><div class="panel" style="background:linear-gradient(145deg,#f0edff,#fff)"><div class="eyebrow">HOW IT WORKS</div><h2 style="font-size:24px">One agent. Four perspectives.</h2><p class="sub">The SideQuest Agent sees the full party — not just the loudest planner.</p><div class="route" style="margin-top:30px"><b>Preferences</b><br>+ <b>Budgets</b><br>+ <b>Tonight's vibe</b><br>↓<br><strong style="color:var(--purple);font-size:20px">One plan for everyone.</strong></div><div class="tags"><span class="tag">4 profiles</span><span class="tag">8 demo venues</span><span class="tag">AI + deterministic scoring</span></div></div></div></section>`)}
function finding(){layout(`<section class="screen" style="max-width:650px;margin:90px auto;text-align:center"><div class="creature" style="width:110px;height:110px"></div><div class="eyebrow">SIDEQUEST AGENT</div><h2>Finding something everyone might actually agree on...</h2><p class="sub" style="margin:auto">Checking 4 profiles, 8 demo experiences and a very real AED 100 limit.</p></section>`);setTimeout(()=>go('plans'),900)}
function planCard(p){return `<article class="plan ${p.id==='competitive'?'featured':''}"><div class="plan-icon">${p.icon}</div><div class="eyebrow">${p.id==='competitive'?'BEST GROUP MATCH':'OPTION '+(p.id==='arcade'?'02':'03')}</div><h3>${p.title}</h3><div class="route">${p.places.map((v,i)=>`${i?' <span>↓</span> ':''}<b>${v.icon} ${esc(v.name)}</b>${v.address?`<small class="place-meta">${esc(v.address)}</small>`:''}`).join('')}</div><div class="price-row"><div class="price">AED ${p.price}<small>per person · estimated</small></div><div class="match">${p.match}% MATCH</div></div><p class="reason">${esc(p.reason)}</p>${p.places.some(v=>v.mapsUrl)?`<a class="maps-link" href="${esc(p.places.find(v=>v.mapsUrl).mapsUrl)}" target="_blank" rel="noreferrer">View places on Google Maps →</a>`:''}</article>`}
function plansView(){layout(`<section class="screen"><button class="back" onclick="go('plan')">← Refine the quest</button><div class="eyebrow">SIDEQUEST AGENT · 3 OPTIONS FOR THE PARTY</div><h2>Pick your adventure.</h2><p class="sub">Complete experiences, not disconnected recommendations. Match scores are calculated from your party's preferences, budgets and vibe.</p><div class="plan-grid" style="margin-top:24px">${plans.map(planCard).join('')}</div><div style="margin-top:28px;display:flex;justify-content:flex-end"><button class="primary" onclick="go('vote')">Take it to the group →</button></div></section>`)}
function vote(){const m=members[state.member];layout(`<section class="screen"><button class="back" onclick="go('plans')">← Plans</button><div class="eyebrow">PARTY VOTE · 04</div><h2>Does the party feel it?</h2><p class="sub">Everyone gets a say. The best plan isn't the loudest person's plan.</p><div class="vote-layout" style="margin-top:22px"><div class="panel"><div class="eyebrow">VOTING AS</div><div class="vote-tabs">${members.map((x,i)=>`<button class="vote-tab ${i===state.member?'active':''}" onclick="state.member=${i};vote()">${x.name}</button>`).join('')}</div>${plans.map(p=>`<div class="vote-plan"><div class="vote-plan-top"><h3>${p.icon} ${p.title}</h3><span class="match">${p.match}%</span></div><div class="vote-buttons">${[['like','❤️ Like'],['maybe','😐 Maybe'],['pass','❌ Pass']].map(([v,t])=>`<button class="${state.votes[m.name]===v?'selected':''}" onclick="cast('${m.name}','${v}')">${t}</button>`).join('')}</div></div>`).join('')}</div><div><div class="panel results"><div class="eyebrow">CURRENT PULSE</div><h3 style="margin-top:9px">Competitive Night</h3>${members.map(x=>`<div class="result-line"><span>${x.name}</span><span>${state.votes[x.name]==='like'?'❤️':state.votes[x.name]==='maybe'?'😐':'❌'}</span></div>`).join('')}</div><div class="alert" style="margin-top:14px"><h3>🤔 No consensus</h3><p style="font-size:12px;color:#815368;line-height:1.5;margin-bottom:15px">Looks like the group wants different things. That is exactly what SideQuest is good at.</p><button class="primary purple" onclick="go('compromise')">✨ Find our compromise</button></div></div></div></section>`)}
function compromise(){const c=compromiseData||{};layout(`<section class="screen"><button class="back" onclick="go('vote')">← Back to votes</button><div class="eyebrow">SIDEQUEST AGENT · CONSENSUS MODE</div><h2>Good groups don't need perfect taste.</h2><p class="sub">They need a plan that makes everyone say, “yeah, I'd do that.”</p><div class="agent-card" style="max-width:760px;margin-top:24px"><div class="eyebrow">✨ WE FOUND A COMPROMISE</div><h2>${c.title||'Everybody gets a win.'}</h2><div class="compromise"><div class="compromise-route">${compromiseRoute()}</div><div class="price-row" style="margin-top:12px"><div class="price">AED ${c.pricePerPerson||68}<small>per person · live agent or fallback</small></div><div class="match">${c.match||96}% GROUP MATCH</div></div></div><div class="checks">${(c.reasons||["Competitive activity for Ronaldo","Gaming experience for Mbappe","Asian food + vegetarian options for Haaland","Within Messi's AED 70 budget"]).map(x=>`<div><span>✓</span> ${x}</div>`).join('')}</div><div class="agent-footer"><div class="big-score">${c.match||96}%<small>GROUP MATCH</small></div><button class="primary" onclick="go('quest')">Accept SideQuest →</button></div></div><p style="color:var(--muted);font-size:11px;margin-top:13px">${c.summary||'SideQuest Agent used the party profiles, votes and available venues to resolve the disagreement.'}</p></section>`)}
function quest(){const stops=[['🎮','Pixel Arcade','Beat one friend at an arcade game.'],['🍜','Seoul Table','Someone must order something they’ve never tried before.'],['🍦','Cloud 9 Mochi','Group votes for MVP of the night.']];layout(`<section class="screen"><div class="eyebrow">QUEST ACCEPTED · TONIGHT</div><h2>Tonight's SideQuest</h2><p class="sub">One night. Three stops. A story you'll keep bringing up.</p><div class="steps" style="margin-top:24px">${stops.map((s,i)=>`<article class="step-card"><div class="step-num">STOP 0${i+1}</div><div class="step-info"><h3>${s[0]} ${s[1]}</h3><p>Challenge: ${s[2]}</p></div><button class="complete ${state.completed>i?'done':''}" onclick="completeStop(${i})">${state.completed>i?'✓ Completed':'Complete'}</button></article>`).join('')}</div></section>`)}
function reveal(){layout(`<section class="screen"><div class="eyebrow">QUEST COMPLETE · +250 GROUP XP</div><h2>The party has a new story.</h2><div class="reveal"><div class="eyebrow">✨ NEW VIBIE DISCOVERED!</div><div class="creature"></div><h2>GLITCH</h2><div class="rarity">UNCOMMON · COMPETITIVE</div><p style="color:#d8d3f3;font-size:13px">A tiny spark of friendly rivalry. Glitch appears wherever a little competition turns into a great night.</p><div class="xp">+250 GROUP XP</div><small style="color:#c9c6de">Discovered by Weekend Warriors</small></div><button class="primary purple" onclick="go('collection')">View collection →</button></section>`)}
function collection(){layout(`<section class="screen"><div class="eyebrow">WEEKEND WARRIORS · LEVEL 4</div><h2>Your party's collection.</h2><div class="price-row" style="max-width:460px;margin:20px 0 24px"><div><strong>VIBIES</strong><div class="progress"><i></i></div></div><div style="font-weight:800">4 / 50</div></div><div class="collection-grid">${[['☕','Brewbie','Chill'],['👾','Glitch','Competitive'],['🌊','Drift','Explorer'],['✨','Luma','Foodie'],['?','Locked','???'],['?','Locked','???'],['?','Locked','???'],['?','Locked','???']].map((x,i)=>`<article class="collection-card ${i>3?'locked':''}"><div class="vibie-icon">${x[0]}</div><h3>${x[1]}</h3><small>${x[2]}</small></article>`).join('')}</div><div style="text-align:center;margin-top:35px"><p class="sub" style="margin:auto">Your friends are your party. Your city is your map. AI is your game master.</p><br><button class="primary" onclick="resetDemo()">Plan another SideQuest ↻</button></div></section>`)}
function go(screen){state.screen=screen;({signin:signIn,home,profile,friends,invite,plan,finding,plans:plansView,vote,compromise,quest,reveal,collection}[screen])()}function setVibe(v){state.vibe=v;plan()}function findPlans(){finding()}function cast(name,v){state.votes[name]=v;vote()}function completeStop(i){if(i===state.completed){state.completed++;state.completed===3?setTimeout(()=>go('reveal'),400):quest()}else quest()}function resetDemo(){state={screen:'home',vibe:'surprise',member:0,votes:{Ronaldo:'like',Messi:'pass',Haaland:'like',Mbappe:'maybe'},completed:0,authed:true,name:state.name,handle:state.handle,city:state.city,friends:state.friends};compromiseData=null;home()}
function compromiseRoute(){const c=compromiseData||{stops:[{icon:'🎮',name:'Pixel Arcade'},{icon:'🍜',name:'Seoul Table'},{icon:'🍦',name:'Cloud 9 Mochi'}]};return (c.stops||[]).map((s,i)=>`${i?' <span>↓</span> ':''}${s.icon||'✦'} ${s.name}`).join('')}
async function findCompromise(){layout(`<section class="screen" style="max-width:650px;margin:90px auto;text-align:center"><div class="creature" style="width:110px;height:110px"></div><div class="eyebrow">SIDEQUEST AGENT · LIVE</div><h2>Reading the room...</h2><p class="sub" style="margin:auto">Comparing profiles, votes, budgets and live context. The fallback is ready if a provider is unavailable.</p></section>`);const payload={location:state.location||state.city||'Dubai',request:'Something fun where we can eat and do an activity.',group:members.map(m=>({name:m.name,preferences:m.tags,budget:m.budget})),votes:state.votes,plans:activePlans.map(p=>({id:p.id,title:p.title,price:p.price,match:p.match,places:(p.places||[]).map(v=>v.id)})),venues:activePlans.flatMap(p=>p.places||[])};try{const response=await fetch('/api/agent/compromise',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(data.ok&&data.compromise)compromiseData=data.compromise}catch(error){compromiseData=null}originalGo('compromise')}
state.authed?home():signIn();
const originalGo=go;go=function(screen){if(screen==='compromise')return findCompromise();return originalGo(screen)};
let activePlans=plans;
const originalPlansView=plansView;
plansView=function(){layout(`<section class="screen"><button class="back" onclick="go('plan')">← Refine the quest</button><div class="eyebrow">SIDEQUEST AGENT · 3 OPTIONS FOR YOUR PARTY</div><h2>Pick your adventure.</h2><p class="sub">These plans were generated from your request, vibe, budget and the current venue catalog.</p><div class="plan-grid" style="margin-top:24px">${activePlans.map(planCard).join('')}</div><div style="margin-top:28px;display:flex;justify-content:flex-end"><button class="primary" onclick="go('vote')">Take it to the group →</button></div></section>`)};
findPlans=async function(){const request=document.querySelector('.request')?.value||'Something fun where we can eat and do an activity.';const budget=Number(document.querySelector('.field:nth-of-type(2) .choice.active')?.textContent.replace(/[^0-9]/g,''))||100;layout(`<section class="screen" style="max-width:650px;margin:90px auto;text-align:center"><div class="creature" style="width:110px;height:110px"></div><div class="eyebrow">SIDEQUEST AGENT · LIVE</div><h2>Building plans around your party...</h2><p class="sub" style="margin:auto">Finding real places near you and matching them to the party.</p></section>`);const payload={location:state.location||state.city||'Dubai',request,budget,vibe:state.vibe,group:members.map(m=>({name:m.name,preferences:m.tags,budget:m.budget})),venues:Object.values(venues).map(v=>({id:v.id,name:v.name,icon:v.icon,estimatedPrice:v.price,tags:v.tags}))};try{const response=await fetch('/api/agent/plans',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(data.ok&&Array.isArray(data.plans)&&data.plans.length===3)activePlans=data.plans}catch(error){activePlans=plans}plansView()};
let locationRequested=false;
function requestLocation(){if(locationRequested||state.location)return Promise.resolve();locationRequested=true;return new Promise(resolve=>{if(!navigator.geolocation)return resolve();navigator.geolocation.getCurrentPosition(position=>{state.location={lat:position.coords.latitude,lng:position.coords.longitude,city:state.city};resolve()},()=>resolve(),{enableHighAccuracy:false,timeout:7000,maximumAge:300000})})}
const generatedFindPlans=findPlans;findPlans=async function(){await requestLocation();return generatedFindPlans()};
document.addEventListener('click',event=>{const button=event.target.closest('.field .choice');if(!button)return;const field=button.closest('.field');if(field?.querySelector('label')?.textContent.includes('BUDGET')||field?.querySelector('label')?.textContent.includes('WHEN')){field.querySelectorAll('.choice').forEach(x=>x.classList.remove('active'));button.classList.add('active')}});
let memoryFiles=[];let memoryVideoUrl='';
function collection(){layout(`<section class="screen"><div class="eyebrow">WEEKEND WARRIORS · LEVEL 4</div><h2>Your party's collection.</h2><div class="price-row" style="max-width:460px;margin:20px 0 24px"><div><strong>VIBIES</strong><div class="progress"><i></i></div></div><div style="font-weight:800">4 / 50</div></div><div class="collection-grid">${[['☕','Brewbie','Chill'],['👾','Glitch','Competitive'],['🌊','Drift','Explorer'],['✨','Luma','Foodie'],['?','Locked','???'],['?','Locked','???'],['?','Locked','???'],['?','Locked','???']].map((x,i)=>`<article class="collection-card ${i>3?'locked':''}"><div class="vibie-icon">${x[0]}</div><h3>${x[1]}</h3><small>${x[2]}</small></article>`).join('')}</div><div class="memory-banner"><div><div class="eyebrow">ONE LAST THING</div><h3>Turn tonight into a memory.</h3><p>Drop in the photos and clips from your SideQuest. We’ll cut them into a tiny party edit.</p></div><button class="primary purple" onclick="go('memories')">🎞 Make our edit →</button></div></section>`)}
function memories(){layout(`<section class="screen"><button class="back" onclick="go('collection')">← Collection</button><div class="eyebrow">MEMORY LAB · FINAL STOP</div><h2>Your night, remixed.</h2><p class="sub">Upload the moments that made the SideQuest yours. SideQuest will stitch them into a shareable trip edit locally in your browser.</p><div class="memory-layout"><div class="panel upload-panel"><label class="dropzone"><input id="memory-input" type="file" accept="image/*,video/*" multiple onchange="handleMemoryFiles(this.files)"><span class="upload-icon">＋</span><strong>Drop photos & clips here</strong><small>JPG, PNG, MP4, MOV · up to 12 files</small></label><div class="media-grid">${memoryFiles.map((file,i)=>`<div class="media-tile"><span>${file.type.startsWith('video/')?'▶':'✦'}</span><small>${esc(file.name).slice(0,18)}</small><button onclick="removeMemory(${i})">×</button></div>`).join('')}</div><button class="primary purple" ${memoryFiles.length?'':'disabled'} onclick="generateMemoryEdit()">✨ Generate our trip edit</button></div><div class="panel memory-preview"><div class="eyebrow">PREVIEW</div>${memoryVideoUrl?`<video class="generated-video" controls autoplay loop src="${memoryVideoUrl}"></video><a class="download-edit" download="weekend-warriors-sidequest.webm" href="${memoryVideoUrl}">Download edit ↓</a>`:`<div class="preview-empty"><div class="film-orb">✦</div><h3>Your highlight reel goes here</h3><p>Upload a few moments to unlock the final SideQuest reward.</p></div>`}</div></div></section>`)}
function handleMemoryFiles(files){memoryFiles=[...memoryFiles,...Array.from(files).slice(0,12-memoryFiles.length)];memories()}
function removeMemory(index){memoryFiles.splice(index,1);memories()}
async function generateMemoryEdit(){if(!memoryFiles.length)return;const button=document.querySelector('.upload-panel .primary');if(button){button.disabled=true;button.textContent='Cutting the memories…'}const canvas=document.createElement('canvas');canvas.width=720;canvas.height=720;const ctx=canvas.getContext('2d');const stream=canvas.captureStream(30);const mime=MediaRecorder.isTypeSupported('video/webm;codecs=vp9')?'video/webm;codecs=vp9':'video/webm';const recorder=new MediaRecorder(stream,{mimeType:mime});const chunks=[];recorder.ondataavailable=e=>e.data.size&&chunks.push(e.data);const stopped=new Promise(resolve=>recorder.onstop=resolve);recorder.start();for(const file of memoryFiles){await drawMemoryFrame(ctx,canvas,file);await new Promise(resolve=>setTimeout(resolve,1800))}recorder.stop();await stopped;memoryVideoUrl=URL.createObjectURL(new Blob(chunks,{type:mime}));memories()}
async function drawMemoryFrame(ctx,canvas,file){ctx.fillStyle='#171928';ctx.fillRect(0,0,canvas.width,canvas.height);const media=file.type.startsWith('video/')?document.createElement('video'):new Image();const url=URL.createObjectURL(file);media.src=url;media.muted=true;media.playsInline=true;await new Promise(resolve=>{media.onload=resolve;media.onloadeddata=resolve;media.onerror=resolve});const scale=Math.max(canvas.width/(media.videoWidth||media.width),canvas.height/(media.videoHeight||media.height));const w=(media.videoWidth||media.width)*scale,h=(media.videoHeight||media.height)*scale;ctx.drawImage(media,(canvas.width-w)/2,(canvas.height-h)/2,w,h);ctx.fillStyle='rgba(21,24,39,.28)';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#fff';ctx.font='700 30px Plus Jakarta Sans';ctx.fillText('WEEKEND WARRIORS',42,canvas.height-72);ctx.font='500 18px DM Mono';ctx.fillStyle='#f9db6b';ctx.fillText('SIDEQUEST · TONIGHT',42,canvas.height-38);if(file.type.startsWith('video/')){media.currentTime=0;await media.play().catch(()=>{});const draw=()=>{if(!media.paused&&!media.ended){ctx.drawImage(media,(canvas.width-w)/2,(canvas.height-h)/2,w,h);requestAnimationFrame(draw)}};draw()}URL.revokeObjectURL(url)}
const goWithMemories=go;go=function(screen){if(screen==='memories')return memories();return goWithMemories(screen)};
// Branded 9:16 template renderer: collage pages instead of a plain slideshow.
generateMemoryEdit=async function(){if(!memoryFiles.length)return;const button=document.querySelector('.upload-panel .primary');if(button){button.disabled=true;button.textContent='Rendering the memory template…'}const canvas=document.createElement('canvas');canvas.width=720;canvas.height=1280;const ctx=canvas.getContext('2d');const stream=canvas.captureStream(30);const mime=MediaRecorder.isTypeSupported('video/webm;codecs=vp9')?'video/webm;codecs=vp9':'video/webm';const recorder=new MediaRecorder(stream,{mimeType:mime});const chunks=[];recorder.ondataavailable=e=>e.data.size&&chunks.push(e.data);const stopped=new Promise(resolve=>recorder.onstop=resolve);recorder.start();await drawTemplatePage(ctx,canvas,[],0);await new Promise(r=>setTimeout(r,1300));for(let i=0;i<memoryFiles.length;i+=4){await drawTemplatePage(ctx,canvas,memoryFiles.slice(i,i+4),Math.floor(i/4)+1);await new Promise(r=>setTimeout(r,2400))}await drawTemplatePage(ctx,canvas,[],99);await new Promise(r=>setTimeout(r,1300));recorder.stop();await stopped;memoryVideoUrl=URL.createObjectURL(new Blob(chunks,{type:mime}));memories()};
async function drawTemplatePage(ctx,canvas,files,page){const w=canvas.width,h=canvas.height;const gradient=ctx.createLinearGradient(0,0,w,h);gradient.addColorStop(0,'#211b4b');gradient.addColorStop(.55,'#5c45c7');gradient.addColorStop(1,'#f39a58');ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);ctx.fillStyle='rgba(255,255,255,.08)';for(let x=0;x<w;x+=44)for(let y=0;y<h;y+=44)ctx.fillRect(x,y,2,2);ctx.fillStyle='#f9db6b';ctx.font='700 22px DM Mono';ctx.fillText('SIDEQUEST · MEMORY LAB',48,72);ctx.fillStyle='#fff';ctx.font='800 58px Plus Jakarta Sans';ctx.fillText(page===0?'WEEKEND':page===99?'QUEST COMPLETE':'WARRIORS',48,150);ctx.fillText(page===0?'WARRIORS':page===99?'GLITCH UNLOCKED':'MEMORY EDIT',48,215);if(page===0||page===99){ctx.font='500 24px Plus Jakarta Sans';ctx.fillStyle='#e4defa';ctx.fillText(page===0?'Tonight became a story.':'+250 GROUP XP · ONE FOR THE COLLECTION',48,270);if(page===99){ctx.font='120px serif';ctx.fillText('👾',48,510);ctx.font='800 54px Plus Jakarta Sans';ctx.fillStyle='#f9db6b';ctx.fillText('GLITCH',48,660)}else{ctx.font='170px serif';ctx.fillText('✦',250,620)}return}const slots=[[48,320,290,370],[382,320,290,370],[48,720,290,370],[382,720,290,370]];for(let i=0;i<slots.length;i++){const [x,y,sw,sh]=slots[i];ctx.save();roundRect(ctx,x,y,sw,sh,24);ctx.clip();if(files[i])await drawAsset(ctx,files[i],x,y,sw,sh);else{ctx.fillStyle='rgba(255,255,255,.14)';ctx.fillRect(x,y,sw,sh);ctx.fillStyle='#fff';ctx.font='60px serif';ctx.fillText('✦',x+115,y+190)}ctx.restore();ctx.fillStyle='rgba(21,24,39,.62)';ctx.fillRect(x,y+sh-42,sw,42);ctx.fillStyle='#fff';ctx.font='500 15px DM Mono';ctx.fillText(files[i]?`0${i+1} · SIDEQUEST`:'NEXT MEMORY',x+14,y+sh-15)}ctx.fillStyle='#fff';ctx.font='700 21px Plus Jakarta Sans';ctx.fillText('FRIENDS ARE THE PARTY',48,1160);ctx.fillStyle='#f9db6b';ctx.font='500 18px DM Mono';ctx.fillText('YOUR CITY IS THE MAP ✦',48,1200)}
function roundRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}
async function drawAsset(ctx,file,x,y,w,h){const url=URL.createObjectURL(file);const media=file.type.startsWith('video/')?document.createElement('video'):new Image();media.src=url;media.muted=true;media.playsInline=true;await new Promise(resolve=>{media.onload=resolve;media.onloadeddata=resolve;media.onerror=resolve});const mw=media.videoWidth||media.width||1,mh=media.videoHeight||media.height||1,scale=Math.max(w/mw,h/mh),dw=mw*scale,dh=mh*scale;ctx.drawImage(media,x+(w-dw)/2,y+(h-dh)/2,dw,dh);URL.revokeObjectURL(url)}
let aiBlueprint=null;let memoryStatus='';
memories=function(){layout(`<section class="screen"><button class="back" onclick="go('collection')">← Collection</button><div class="eyebrow">MEMORY LAB · FINAL STOP</div><h2>Your night, remixed.</h2><p class="sub">Choose multiple photos and clips, then pick a regular template cut or let SideQuest Agent choreograph the edit.</p><div class="memory-layout"><div class="panel upload-panel"><label class="dropzone"><input id="memory-input" type="file" accept="image/*,video/*" multiple onchange="handleMemoryFiles(this.files)"><span class="upload-icon">＋</span><strong>Select multiple photos & clips</strong><small>JPG, PNG, MP4, MOV · up to 12 files</small></label><div class="media-grid">${memoryFiles.map((file,i)=>`<div class="media-tile"><span>${file.type.startsWith('video/')?'▶':'✦'}</span><small>${esc(file.name).slice(0,18)}</small><button onclick="removeMemory(${i})">×</button></div>`).join('')}</div><div class="edit-actions"><button class="template-button" ${memoryFiles.length?'':'disabled'} onclick="aiBlueprint=null;generateMemoryEdit()">🎞 Template cut</button><button class="primary purple" ${memoryFiles.length?'':'disabled'} onclick="requestAICut()">✨ AI choreographed cut</button></div>${memoryStatus?`<p class="agent-status">${memoryStatus}</p>`:''}</div><div class="panel memory-preview"><div class="eyebrow">PREVIEW</div>${memoryVideoUrl?`<video class="generated-video" controls autoplay loop src="${memoryVideoUrl}"></video><a class="download-edit" download="weekend-warriors-sidequest.webm" href="${memoryVideoUrl}">Download edit ↓</a>`:`<div class="preview-empty"><div class="film-orb">✦</div><h3>Your highlight reel goes here</h3><p>Upload a few moments to unlock the final SideQuest reward.</p></div>`}</div></div></section>`)};
async function requestAICut(){if(!memoryFiles.length)return;memoryStatus='SideQuest Agent is choosing the story arc…';memories();try{const response=await fetch('/api/agent/video-edit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({style:'playful cinematic friend-group recap',files:memoryFiles.map((file,index)=>({index,name:file.name,type:file.type}))})});const data=await response.json();if(data.ok&&data.blueprint){aiBlueprint=data.blueprint;const order=aiBlueprint.order||[];memoryFiles=order.map(i=>memoryFiles[i]).filter(Boolean);memoryStatus=data.source==='openrouter'?'AI choreographed your edit. Rendering the template…':'AI fallback selected a fun edit order. Rendering…';generateMemoryEdit()}else{memoryStatus='Could not create an AI cut, so the template cut is ready.';memories()}}catch(error){memoryStatus='AI is unavailable, so the template cut is ready.';memories()}}
let selectedTemplate='neon';
function chooseTemplate(name){selectedTemplate=name;memories()}
memories=function(){layout(`<section class="screen"><button class="back" onclick="go('collection')">← Collection</button><div class="eyebrow">MEMORY LAB · FINAL STOP</div><h2>Your night, remixed.</h2><p class="sub">Choose multiple photos and clips, pick a visual template, then let SideQuest cut the memory.</p><div class="memory-layout"><div class="panel upload-panel"><label class="dropzone"><input id="memory-input" type="file" accept="image/*,video/*" multiple onchange="handleMemoryFiles(this.files)"><span class="upload-icon">＋</span><strong>Select multiple photos & clips</strong><small>JPG, PNG, MP4, MOV · up to 12 files</small></label><div class="media-grid">${memoryFiles.map((file,i)=>`<div class="media-tile"><span>${file.type.startsWith('video/')?'▶':'✦'}</span><small>${esc(file.name).slice(0,18)}</small><button onclick="removeMemory(${i})">×</button></div>`).join('')}</div><div class="eyebrow template-label">CHOOSE A TEMPLATE</div><div class="template-picker">${[['neon','⚡','Neon Arcade','Electric + energetic'],['sunset','🌇','Sunset Scrapbook','Warm + nostalgic'],['polaroid','📸','Polaroid Journal','Soft + candid']].map(t=>`<button class="template-choice ${selectedTemplate===t[0]?'selected':''}" onclick="chooseTemplate('${t[0]}')"><span>${t[1]}</span><strong>${t[2]}</strong><small>${t[3]}</small></button>`).join('')}</div><div class="edit-actions"><button class="template-button" ${memoryFiles.length?'':'disabled'} onclick="aiBlueprint=null;generateMemoryEdit()">🎞 Template cut</button><button class="primary purple" ${memoryFiles.length?'':'disabled'} onclick="requestAICut()">✨ AI choreographed cut</button></div>${memoryStatus?`<p class="agent-status">${memoryStatus}</p>`:''}</div><div class="panel memory-preview"><div class="eyebrow">PREVIEW · ${selectedTemplate.toUpperCase()}</div>${memoryVideoUrl?`<video class="generated-video" controls autoplay loop src="${memoryVideoUrl}"></video><a class="download-edit" download="weekend-warriors-sidequest.webm" href="${memoryVideoUrl}">Download edit ↓</a>`:`<div class="preview-empty"><div class="film-orb">✦</div><h3>Your highlight reel goes here</h3><p>Upload moments, choose a look, and make the final memory.</p></div>`}</div></div></section>`)};
drawTemplatePage=async function(ctx,canvas,files,page){const w=canvas.width,h=canvas.height;const themes={neon:{bg:['#211b4b','#5c45c7','#f39a58'],ink:'#fff',accent:'#f9db6b',sub:'FRIENDS ARE THE PARTY'},sunset:{bg:['#722f42','#e16e5c','#ffc978'],ink:'#fffaf0',accent:'#ffe2a4',sub:'GOOD TIMES, GOLDEN HOUR'},polaroid:{bg:['#f7efe0','#e7d6bd','#c99b70'],ink:'#33283d',accent:'#b64d65',sub:'A LITTLE MOMENT, TOGETHER'}};const t=themes[selectedTemplate]||themes.neon;const gradient=ctx.createLinearGradient(0,0,w,h);gradient.addColorStop(0,t.bg[0]);gradient.addColorStop(.55,t.bg[1]);gradient.addColorStop(1,t.bg[2]);ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);ctx.fillStyle=selectedTemplate==='polaroid'?'rgba(255,255,255,.18)':'rgba(255,255,255,.08)';for(let x=0;x<w;x+=44)for(let y=0;y<h;y+=44)ctx.fillRect(x,y,2,2);ctx.fillStyle=t.accent;ctx.font='700 22px DM Mono';ctx.fillText('SIDEQUEST · MEMORY LAB',48,72);ctx.fillStyle=t.ink;ctx.font='800 58px Plus Jakarta Sans';ctx.fillText(page===0?'WEEKEND':page===99?'QUEST COMPLETE':'WARRIORS',48,150);ctx.fillText(page===0?'WARRIORS':page===99?'GLITCH UNLOCKED':'MEMORY EDIT',48,215);if(page===0||page===99){ctx.font='500 24px Plus Jakarta Sans';ctx.fillStyle=t.ink;ctx.globalAlpha=.8;ctx.fillText(page===0?'Tonight became a story.':'+250 GROUP XP · ONE FOR THE COLLECTION',48,270);ctx.globalAlpha=1;ctx.font='150px serif';ctx.fillText(page===99?'👾':'✦',page===99?48:250,620);if(page===99){ctx.font='800 54px Plus Jakarta Sans';ctx.fillStyle=t.accent;ctx.fillText('GLITCH',48,660)}return}const slots=[[48,320,290,370],[382,320,290,370],[48,720,290,370],[382,720,290,370]];for(let i=0;i<slots.length;i++){const [x,y,sw,sh]=slots[i];ctx.save();if(selectedTemplate==='polaroid'){ctx.fillStyle='#fffaf3';ctx.shadowColor='rgba(40,20,30,.2)';ctx.shadowBlur=15;ctx.shadowOffsetY=8;ctx.fillRect(x-9,y-9,sw+18,sh+35);ctx.shadowColor='transparent'}else{roundRect(ctx,x,y,sw,sh,24);ctx.clip()}if(files[i])await drawAsset(ctx,files[i],x,y,sw,sh);else{ctx.fillStyle=selectedTemplate==='polaroid'?'#eadfcf':'rgba(255,255,255,.14)';ctx.fillRect(x,y,sw,sh);ctx.fillStyle=t.accent;ctx.font='60px serif';ctx.fillText('✦',x+115,y+190)}ctx.restore();ctx.fillStyle=selectedTemplate==='polaroid'?'rgba(51,40,61,.72)':'rgba(21,24,39,.62)';ctx.fillRect(x,y+sh-42,sw,42);ctx.fillStyle='#fff';ctx.font='500 15px DM Mono';ctx.fillText(files[i]?`0${i+1} · SIDEQUEST`:'NEXT MEMORY',x+14,y+sh-15)}ctx.fillStyle=t.ink;ctx.font='700 21px Plus Jakarta Sans';ctx.fillText(t.sub,48,1160);ctx.fillStyle=t.accent;ctx.font='500 18px DM Mono';ctx.fillText(selectedTemplate==='polaroid'?'DUBAI · TONIGHT':'YOUR CITY IS THE MAP ✦',48,1200)}
let locationCoords=null;let locationStatus='Dubai demo area';let geoapifyUsed=false;
const basePlan=plan;
plan=function(){basePlan();const panel=document.querySelector('.form-layout .panel');if(!panel||document.querySelector('#location-field'))return;const field=document.createElement('div');field.id='location-field';field.className='field location-field';field.innerHTML=`<label>WHERE ARE WE?</label><div class="location-row"><button class="location-button" onclick="useMyLocation()">◎ Use my current location</button><span id="location-status">${locationStatus}</span></div><small class="location-note">Your location is only used to find nearby places for this plan.</small>`;panel.insertBefore(field,panel.firstChild)};
function useMyLocation(){const status=document.querySelector('#location-status');if(status)status.textContent='Asking for permission…';if(!navigator.geolocation){locationStatus='Location is not supported in this browser';if(status)status.textContent=locationStatus;return}navigator.geolocation.getCurrentPosition(pos=>{locationCoords={latitude:pos.coords.latitude,longitude:pos.coords.longitude};locationStatus='Location ready · nearby places will be used';if(status)status.textContent=locationStatus},()=>{locationStatus='Could not access location · using Dubai demo area';if(status)status.textContent=locationStatus},{enableHighAccuracy:false,timeout:10000,maximumAge:300000})}
findPlans=async function(){const request=document.querySelector('.request')?.value||'Something fun where we can eat and do an activity.';const budget=Number(document.querySelector('.field:nth-of-type(2) .choice.active')?.textContent.replace(/[^0-9]/g,''))||100;layout(`<section class="screen" style="max-width:650px;margin:90px auto;text-align:center"><div class="creature" style="width:110px;height:110px"></div><div class="eyebrow">SIDEQUEST AGENT · LIVE</div><h2>${locationCoords?'Finding places near you…':'Building plans around your party…'}</h2><p class="sub" style="margin:auto">${locationCoords?'Searching Geoapify nearby places, then matching them to your party.':'Reading your request and matching it against the available experiences.'}</p></section>`);const payload={location:locationCoords?'current location':state.city||'Dubai',latitude:locationCoords?.latitude,longitude:locationCoords?.longitude,request,budget,vibe:state.vibe,group:members.map(m=>({name:m.name,preferences:m.tags,budget:m.budget})),venues:Object.values(venues).map(v=>({id:v.id,name:v.name,icon:v.icon,estimatedPrice:v.price,tags:v.tags}))};try{const response=await fetch('/api/agent/plans',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(data.ok&&Array.isArray(data.plans)&&data.plans.length===3){activePlans=data.plans;geoapifyUsed=Boolean(data.geoapifyUsed);locationStatus=geoapifyUsed?'Live nearby places':'Dubai demo places'}}catch(error){activePlans=plans;geoapifyUsed=false}plansView()};
let voteChoices={};
function initializePlanVotes(){voteChoices={};members.forEach(member=>{voteChoices[member.name]={};activePlans.forEach((p,index)=>{voteChoices[member.name][p.id]=index===0?(member.name===members[1].name?'pass':member.name===members[2].name?'like':'maybe'):'maybe'})})}
const previousFindPlans=findPlans;findPlans=async function(){await previousFindPlans();initializePlanVotes()};
cast=function(name,value,planId){if(!voteChoices[name])voteChoices[name]={};voteChoices[name][planId]=value;vote()};
vote=function(){const m=members[state.member];layout(`<section class="screen"><button class="back" onclick="go('plans')">← Plans</button><div class="eyebrow">PARTY VOTE · 04</div><h2>Does the party feel it?</h2><p class="sub">Each person can vote on every plan individually. Nothing gets overwritten.</p><div class="vote-layout" style="margin-top:22px"><div class="panel"><div class="eyebrow">VOTING AS</div><div class="vote-tabs">${members.map((x,i)=>`<button class="vote-tab ${i===state.member?'active':''}" onclick="state.member=${i};vote()">${x.name}</button>`).join('')}</div>${activePlans.map(p=>`<div class="vote-plan"><div class="vote-plan-top"><h3>${p.icon||'✦'} ${esc(p.title)}</h3><span class="match">${p.match||80}%</span></div><div class="vote-route">${(p.places||[]).map(v=>esc(v.name)).join(' · ')}</div><div class="vote-buttons">${[['like','❤️ Like'],['maybe','😐 Maybe'],['pass','❌ Pass']].map(([v,t])=>`<button class="${voteChoices[m.name]?.[p.id]===v?'selected':''}" onclick="cast('${m.name}','${v}','${p.id}')">${t}</button>`).join('')}</div></div>`).join('')}</div><div><div class="panel results"><div class="eyebrow">CURRENT PULSE</div><h3 style="margin-top:9px">Plan-by-plan votes</h3>${activePlans.map(p=>{const values=members.map(x=>voteChoices[x.name]?.[p.id]);return `<div class="result-line"><span>${esc(p.title)}</span><span>${values.filter(v=>v==='like').length} ❤️ · ${values.filter(v=>v==='maybe').length} 😐 · ${values.filter(v=>v==='pass').length} ❌</span></div>`}).join('')}</div><div class="alert" style="margin-top:14px"><h3>🤔 No consensus</h3><p style="font-size:12px;color:#815368;line-height:1.5;margin-bottom:15px">The party has different favorites. Let the Agent find the overlap.</p><button class="primary purple" onclick="go('compromise')">✨ Find our compromise</button></div></div></div></section>`)};
findCompromise=async function(){layout(`<section class="screen" style="max-width:650px;margin:90px auto;text-align:center"><div class="creature" style="width:110px;height:110px"></div><div class="eyebrow">SIDEQUEST AGENT · LIVE</div><h2>Reading the room...</h2><p class="sub" style="margin:auto">Comparing your generated plans, individual votes, budgets and nearby venues.</p></section>`);const nearbyVenues=[...new Map(activePlans.flatMap(p=>p.places||[]).map(v=>[v.id,v])).values()];const payload={location:locationCoords?'current location':state.city||'Dubai',latitude:locationCoords?.latitude,longitude:locationCoords?.longitude,request:'Something fun where we can eat and do an activity.',group:members.map(m=>({name:m.name,preferences:m.tags,budget:m.budget})),votes:voteChoices,plans:activePlans.map(p=>({id:p.id,title:p.title,price:p.price,match:p.match,places:(p.places||[]).map(v=>v.id)})),venues:nearbyVenues.map(v=>({id:v.id,name:v.name,icon:v.icon,estimatedPrice:v.estimatedPrice||v.price||35,tags:v.tags||[],address:v.address||''}))};try{const response=await fetch('/api/agent/compromise',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(data.ok&&data.compromise)compromiseData=data.compromise}catch(error){compromiseData=null}originalGo('compromise')};
planCard=function(p){const live=p.places?.some(v=>String(v.id).startsWith('geo_'));return `<article class="plan refined-plan ${p.id==='competitive'||p.match>=92?'featured':''}"><div class="plan-topline"><span class="plan-icon">${p.icon||'✦'}</span><span class="plan-live">${live?'● NEAR YOU':'CURATED PICK'}</span></div><div class="eyebrow">${p.match>=92?'BEST GROUP MATCH':'OPTION'}</div><h3>${esc(p.title)}</h3><div class="route refined-route">${(p.places||[]).map((v,i)=>`<div class="route-stop"><span class="stop-index">0${i+1}</span><span class="stop-icon">${v.icon||'📍'}</span><span><b>${esc(v.name||'Nearby place')}</b><small>${esc(v.address||v.category||'Local experience')}</small></span></div>${i<2?'<div class="route-line"></div>':''}`).join('')}</div><div class="plan-bottom"><div class="price">AED ${p.price||'—'}<small>estimated / person</small></div><div class="match">${p.match||80}%<small>GROUP MATCH</small></div></div><p class="reason">${esc(p.reason||'A plan shaped around the whole party.')}</p></article>`};
vote=function(){const m=members[state.member];layout(`<section class="screen"><button class="back" onclick="go('plans')">← Plans</button><div class="eyebrow">PARTY VOTE · 04</div><h2>Does the party feel it?</h2><p class="sub">Everyone gets a say on the plans SideQuest just found${geoapifyUsed?' nearby.':'.'}</p><div class="vote-layout" style="margin-top:22px"><div class="panel"><div class="eyebrow">VOTING AS</div><div class="vote-tabs">${members.map((x,i)=>`<button class="vote-tab ${i===state.member?'active':''}" onclick="state.member=${i};vote()">${x.name}</button>`).join('')}</div>${activePlans.map(p=>`<div class="vote-plan"><div class="vote-plan-top"><h3>${p.icon||'✦'} ${esc(p.title)}</h3><span class="match">${p.match||80}%</span></div><div class="vote-route">${(p.places||[]).map(v=>esc(v.name)).join(' · ')}</div><div class="vote-buttons">${[['like','❤️ Like'],['maybe','😐 Maybe'],['pass','❌ Pass']].map(([v,t])=>`<button class="${state.votes[m.name]===v?'selected':''}" onclick="cast('${m.name}','${v}')">${t}</button>`).join('')}</div></div>`).join('')}</div><div><div class="panel results"><div class="eyebrow">CURRENT PULSE</div><h3 style="margin-top:9px">Party vote</h3>${members.map(x=>`<div class="result-line"><span>${x.name}</span><span>${state.votes[x.name]==='like'?'❤️':state.votes[x.name]==='maybe'?'😐':'❌'}</span></div>`).join('')}</div><div class="alert" style="margin-top:14px"><h3>🤔 No consensus</h3><p style="font-size:12px;color:#815368;line-height:1.5;margin-bottom:15px">Looks like the group wants different things. Let the Agent find the overlap.</p><button class="primary purple" onclick="go('compromise')">✨ Find our compromise</button></div></div></div></section>`)};
findCompromise=async function(){layout(`<section class="screen" style="max-width:650px;margin:90px auto;text-align:center"><div class="creature" style="width:110px;height:110px"></div><div class="eyebrow">SIDEQUEST AGENT · LIVE</div><h2>Reading the room...</h2><p class="sub" style="margin:auto">Comparing your live nearby plans, votes, budgets and preferences.</p></section>`);const payload={location:locationCoords?'current location':state.city||'Dubai',latitude:locationCoords?.latitude,longitude:locationCoords?.longitude,request:'Something fun where we can eat and do an activity.',group:members.map(m=>({name:m.name,preferences:m.tags,budget:m.budget})),votes:state.votes,plans:activePlans.map(p=>({id:p.id,title:p.title,price:p.price,match:p.match,places:(p.places||[]).map(v=>v.id)})),venues:Object.values(venues).map(v=>({id:v.id,name:v.name,icon:v.icon,estimatedPrice:v.price,tags:v.tags}))};try{const response=await fetch('/api/agent/compromise',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(data.ok&&data.compromise)compromiseData=data.compromise}catch(error){compromiseData=null}originalGo('compromise')};
// Final interaction bindings: votes are isolated by person + plan, and compromise uses those live plans.
cast=function(name,value,planId){voteChoices[name]??={};voteChoices[name][planId]=value;vote()};
vote=function(){const m=members[state.member];layout(`<section class="screen"><button class="back" onclick="go('plans')">← Plans</button><div class="eyebrow">PARTY VOTE · 04</div><h2>Does the party feel it?</h2><p class="sub">Voting as ${esc(m.name)}. Choose a reaction independently on every plan.</p><div class="vote-layout" style="margin-top:22px"><div class="panel"><div class="eyebrow">VOTING AS</div><div class="vote-tabs">${members.map((x,i)=>`<button class="vote-tab ${i===state.member?'active':''}" onclick="state.member=${i};vote()">${x.name}</button>`).join('')}</div>${activePlans.map(p=>`<div class="vote-plan"><div class="vote-plan-top"><h3>${p.icon||'✦'} ${esc(p.title)}</h3><span class="match">${p.match||80}%</span></div><div class="vote-route">${(p.places||[]).map(v=>esc(v.name)).join(' · ')}</div><div class="vote-buttons">${[['like','❤️ Like'],['maybe','😐 Maybe'],['pass','❌ Pass']].map(([v,t])=>`<button class="${voteChoices[m.name]?.[p.id]===v?'selected':''}" onclick="cast('${m.name}','${v}','${p.id}')">${t}</button>`).join('')}</div></div>`).join('')}</div><div><div class="panel results"><div class="eyebrow">CURRENT PULSE</div><h3 style="margin-top:9px">Plan-by-plan votes</h3>${activePlans.map(p=>{const values=members.map(x=>voteChoices[x.name]?.[p.id]);return `<div class="result-line"><span>${esc(p.title)}</span><span>${values.filter(v=>v==='like').length} ❤️ · ${values.filter(v=>v==='maybe').length} 😐 · ${values.filter(v=>v==='pass').length} ❌</span></div>`}).join('')}</div><div class="alert" style="margin-top:14px"><h3>🤔 No consensus</h3><p style="font-size:12px;color:#815368;line-height:1.5;margin-bottom:15px">The party has different favorites. Let the Agent find the overlap.</p><button class="primary purple" onclick="go('compromise')">✨ Find our compromise</button></div></div></div></section>`)};
findCompromise=async function(){layout(`<section class="screen" style="max-width:650px;margin:90px auto;text-align:center"><div class="creature" style="width:110px;height:110px"></div><div class="eyebrow">SIDEQUEST AGENT · LIVE</div><h2>Reading the room...</h2><p class="sub" style="margin:auto">Comparing the exact plans and individual votes you just made.</p></section>`);const nearbyVenues=[...new Map(activePlans.flatMap(p=>p.places||[]).map(v=>[String(v.id),v])).values()];const payload={location:locationCoords?'current location':state.city||'Dubai',latitude:locationCoords?.latitude,longitude:locationCoords?.longitude,request:document.querySelector('.request')?.value||'Something fun where we can eat and do an activity.',group:members.map(m=>({name:m.name,preferences:m.tags,budget:m.budget})),votes:voteChoices,plans:activePlans.map(p=>({id:p.id,title:p.title,price:p.price,match:p.match,places:(p.places||[]).map(v=>v.id)})),venues:nearbyVenues.map(v=>({id:v.id,name:v.name,icon:v.icon,estimatedPrice:v.estimatedPrice||v.price||35,tags:v.tags||[],address:v.address||''}))};try{const response=await fetch('/api/agent/compromise',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();compromiseData=data.ok&&data.compromise?data.compromise:null}catch(error){compromiseData=null}originalGo('compromise')};
let acceptedPlan=null;
function chooseWinningPlan(){acceptedPlan=activePlans.map(plan=>{const votes=members.map(member=>voteChoices[member.name]?.[plan.id]);return {...plan,likes:votes.filter(v=>v==='like').length,passes:votes.filter(v=>v==='pass').length,maybes:votes.filter(v=>v==='maybe').length}}).sort((a,b)=>(b.likes-a.likes)||(b.match-a.match))[0]||activePlans[0]||null}
const requestCompromise=findCompromise;findCompromise=async function(){chooseWinningPlan();await requestCompromise()};
function questChallenge(place,index){const tags=(place.tags||[]).join(' ');if(index===0)return tags.includes('gaming')||tags.includes('activity')?'Beat one friend at this stop.':'Find the most surprising thing on the menu.';if(index===1)return tags.includes('food')||tags.includes('restaurant')?'Someone orders something they have never tried before.':'Take a group photo that captures the vibe.';return 'Group votes for MVP of the night.'}
quest=function(){const route=acceptedPlan?.places?.length?acceptedPlan.places:(compromiseData?.stops||[]).map(stop=>({id:stop.venueId,name:stop.name,icon:stop.icon,tags:[],challenge:stop.challenge}));layout(`<section class="screen"><div class="eyebrow">QUEST ACCEPTED · TONIGHT</div><h2>${esc(acceptedPlan?.title||compromiseData?.title||"Tonight's SideQuest")}</h2><p class="sub">The party picked this plan. Now turn it into a story.</p><div class="steps" style="margin-top:24px">${route.slice(0,3).map((place,i)=>`<article class="step-card"><div class="step-num">STOP 0${i+1}</div><div class="step-info"><h3>${place.icon||'📍'} ${esc(place.name||'Nearby place')}</h3><p>Challenge: ${esc(place.challenge||questChallenge(place,i))}</p></div><button class="complete ${state.completed>i?'done':''}" onclick="completeStop(${i})">${state.completed>i?'✓ Completed':'Complete'}</button></article>`).join('')}</div></section>`)};
const resetWithAcceptedPlan=resetDemo;resetDemo=function(){acceptedPlan=null;resetWithAcceptedPlan()};
